def valid_parentheses(s: str) -> bool:
    # 映射右括号到对应的左括号
    pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    stack = []

    for ch in s:
        if ch in '([{':
            # 左括号直接入栈
            stack.append(ch)
        else:
            # 右括号必须与栈顶左括号匹配
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    # 所有左括号都必须被闭合
    return not stack


