def has_cycle(nums: list, pos: int) -> bool:
    # 定义链表节点
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    # 空链表直接无环
    if not nums:
        return False

    # 构造链表节点
    nodes = [ListNode(v) for v in nums]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]

    # 根据 pos 连接环
    if pos != -1:
        nodes[-1].next = nodes[pos]

    # 快慢指针判断是否有环
    slow = fast = nodes[0]
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True

    return False


