def binary_tree_max_path_sum(root: list) -> int:
    # 根据层序遍历数组构建二叉树
    if not root or root[0] is None:
        return 0

    class TreeNode:
        def __init__(self, val=0):
            self.val = val
            self.left = None
            self.right = None

    nodes = [None if x is None else TreeNode(x) for x in root]
    # 按层序连接子节点
    child_index = 1
    for i in range(len(nodes)):
        if nodes[i] is None:
            continue
        if child_index < len(nodes):
            nodes[i].left = nodes[child_index]
            child_index += 1
        if child_index < len(nodes):
            nodes[i].right = nodes[child_index]
            child_index += 1

    ans = float('-inf')

    def dfs(node):
        nonlocal ans
        if node is None:
            return 0
        # 左右子树能提供的最大单边贡献，负贡献直接舍弃
        left_gain = max(dfs(node.left), 0)
        right_gain = max(dfs(node.right), 0)
        # 以当前节点为“拐点”的完整路径和
        path_sum = node.val + left_gain + right_gain
        ans = max(ans, path_sum)
        # 返回以当前节点为起点向下的最大单边路径和
        return node.val + max(left_gain, right_gain)

    dfs(nodes[0])
    return ans

def longest_valid_parentheses(s: str) -> int:
    # 栈中存放下标；初始放入 -1 作为“最后一个未匹配位置”的哨兵
    stack = [-1]
    max_len = 0

    for i, ch in enumerate(s):
        if ch == '(':
            # 左括号下标入栈
            stack.append(i)
        else:
            # 遇到右括号，先弹出栈顶，尝试匹配
            stack.pop()

            if not stack:
                # 栈为空说明当前右括号无法匹配，将其下标作为新的哨兵
                stack.append(i)
            else:
                # 栈顶是当前合法子串前一个未匹配位置
                max_len = max(max_len, i - stack[-1])

    return max_len

