def split_array_largest_sum(nums: list, k: int) -> int:
    # 二分查找最小的“最大子数组和”
    # 下界：数组中的最大值（单个元素不能拆）
    # 上界：数组总和（整个数组作为一段）
    lo, hi = max(nums), sum(nums)

    def can_split(limit: int) -> bool:
        """判断能否把数组切成不超过 k 段，使每段和 <= limit"""
        segments = 1
        current = 0
        for x in nums:
            if current + x > limit:
                segments += 1
                current = x
                if segments > k:
                    return False
            else:
                current += x
        return True

    while lo < hi:
        mid = (lo + hi) // 2
        if can_split(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


