def valid_parentheses(s: str) -> bool:
    # 括号总数为奇数时不可能完全匹配
    if len(s) % 2 == 1:
        return False

    # 右括号到左括号的映射
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []

    for ch in s:
        if ch in '([{':
            # 左括号入栈
            stack.append(ch)
        else:
            # 右括号：栈空或类型不匹配则无效
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    # 所有左括号都必须被闭合
    return not stack


