def search_in_rotated_sorted_array(nums: list, target: int) -> int:
    """
    在旋转后的升序数组中查找目标值 target。
    若存在返回其下标，否则返回 -1。

    思路：
    使用二分查找。对于当前区间 [left, right]，中点 mid 将数组分为两半。
    由于数组由两段升序区间构成，因此至少有一半是有序的：
    1. 如果 nums[left] <= nums[mid]，说明左半段有序；
       若 target 在该有序区间内，则收缩到左半段，否则收缩到右半段。
    2. 否则右半段有序；
       若 target 在该有序区间内，则收缩到右半段，否则收缩到左半段。
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if nums[mid] == target:
            return mid

        # 左半段有序
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # 右半段有序
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def coin_change(coins: list, amount: int) -> int:
    # dp[x] 表示凑成金额 x 所需的最少硬币个数
    # 初始化为一个足够大的值，表示暂时无法凑出
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0  # 凑出金额 0 不需要任何硬币

    # 完全背包：正序遍历金额，允许每种硬币重复使用
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1

    # 如果仍为初始值，说明无法凑出该金额
    return dp[amount] if dp[amount] != INF else -1

