    if not root:
        return 0

    # 根据层序遍历数组构建二叉树
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right

    nodes = []
    for val in root:
        if val is None:
            nodes.append(None)
        else:
            nodes.append(TreeNode(val))

    # 按层序连接节点
    child_index = 1
    for i in range(len(nodes)):
        node = nodes[i]
        if node is None:
            continue
        if child_index < len(nodes):
            node.left = nodes[child_index]
            child_index += 1
        if child_index < len(nodes):
            node.right = nodes[child_index]
            child_index += 1

    max_sum = float('-inf')

    def dfs(node):
        nonlocal max_sum
        if node is None:
            return 0

        # 左右子树能提供的最大单边贡献，负数则舍弃
        left_gain = max(dfs(node.left), 0)
        right_gain = max(dfs(node.right), 0)

        # 以当前节点为“拐点”的完整路径和
        current_path_sum = node.val + left_gain + right_gain
        if current_path_sum > max_sum:
            max_sum = current_path_sum

        # 返回以当前节点为端点向下延伸的最大单边路径和
        return node.val + max(left_gain, right_gain)

    dfs(nodes[0])
    return max_sum

