def trapping_rain_water(height: list) -> int:
    """
    计算柱子之间能接的雨水总量。
    采用双指针法：从两端向中间收缩，维护左右两侧的最大高度。
    时间复杂度 O(n)，空间复杂度 O(1)。
    """
    if not height or len(height) < 3:
        return 0

    left, right = 0, len(height) - 1
    left_max = right_max = 0
    result = 0

    while left < right:
        if height[left] < height[right]:
            # 左侧较矮，当前位置的接水量由 left_max 决定
            if height[left] >= left_max:
                left_max = height[left]
            else:
                result += left_max - height[left]
            left += 1
        else:
            # 右侧较矮（或相等），当前位置的接水量由 right_max 决定
            if height[right] >= right_max:
                right_max = height[right]
            else:
                result += right_max - height[right]
            right -= 1

    return result

def minimum_window_substring(s: str, t: str) -> str:
    if not s or not t or len(s) < len(t):
        return ""

    # 统计 t 中每个字符需要的次数
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1

    required = len(need)  # 需要满足的不同字符种类数
    formed = 0            # 当前窗口中已经满足次数要求的字符种类数

    window_count = {}
    left = 0
    best_len = float("inf")
    best_left = 0

    for right, ch in enumerate(s):
        # 右指针字符加入窗口
        window_count[ch] = window_count.get(ch, 0) + 1

        # 如果该字符是 t 中需要的，并且次数刚好达到要求，则满足种类数加一
        if ch in need and window_count[ch] == need[ch]:
            formed += 1

        # 当窗口已经覆盖 t 的全部字符时，尝试收缩左边界
        while left <= right and formed == required:
            current_len = right - left + 1
            if current_len < best_len:
                best_len = current_len
                best_left = left

            left_ch = s[left]
            window_count[left_ch] -= 1

            # 如果移除后不再满足该字符的要求，则合法种类数减一
            if left_ch in need and window_count[left_ch] < need[left_ch]:
                formed -= 1

            left += 1

    if best_len == float("inf"):
        return ""

    return s[best_left:best_left + best_len]


