    high = sum(nums)

    while low < high:
        mid = (low + high) // 2
        if can_split(mid):
            high = mid
        else:
            low = mid + 1

    return low

def trapping_rain_water(height: list) -> int:
    """双指针法计算接雨水总量，时间复杂度 O(n)，空间复杂度 O(1)。"""
    # 少于 3 根柱子无法形成凹槽，接不到水
    if not height or len(height) < 3:
        return 0

    left, right = 0, len(height) - 1
    left_max = 0   # 当前位置左侧出现过的最高柱子
    right_max = 0  # 当前位置右侧出现过的最高柱子
    ans = 0

    while left < right:
        # 哪侧柱子更矮，就结算哪侧：该侧瓶颈已由对应的 max 确定
        if height[left] < height[right]:
            if height[left] >= left_max:
                # 当前柱子更高，更新左最高，此处无法积水
                left_max = height[left]
            else:
                # 当前柱子较矮，可积水为左最高减去自身高度
                ans += left_max - height[left]
            left += 1
        else:
            # 相等时移动右侧同样正确，两侧瓶颈相同不影响结果
            if height[right] >= right_max:
                right_max = height[right]
            else:
                ans += right_max - height[right]
            right -= 1

    return ans


if __name__ == "__main__":
    # 示例验证
    print(trapping_rain_water([0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1]))  # 6
    print(trapping_rain_water([4, 2, 0, 3, 2, 5]))                    # 9
    print(trapping_rain_water([2, 0, 2]))                             # 2
    print(trapping_rain_water([1, 2]))                                # 0

def minimum_window_substring(s: str, t: str) -> str:
    if not s or not t or len(s) < len(t):
        return ""

    # 统计 t 中每个字符的需求次数
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1

    missing = len(t)          # 还缺少的字符总数
    left = 0
    best_len = float("inf")
    best_start = 0

    for right, ch in enumerate(s):
        # 右指针扩张：若该字符仍是所需字符，则缺口减少
        if ch in need:
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1

        # 当窗口已覆盖 t，尝试收缩左指针寻找更短窗口
        while missing == 0:
            # 先更新最优答案
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best_start = left

            # 再移出左指针字符，并补回需求计数
            left_ch = s[left]
            if left_ch in need:
                need[left_ch] += 1
                if need[left_ch] > 0:
                    missing += 1
            left += 1

    if best_len == float("inf"):
        return ""
    return s[best_start:best_start + best_len]

def split_array_largest_sum(nums: list, k: int) -> int:
    # 二分答案：寻找最小的 mid，使得数组能被分成不超过 k 段且每段和 <= mid
    lo, hi = max(nums), sum(nums)

    def can_split(mid: int) -> bool:
        # 贪心校验：从左到右累加，超过 mid 就新开一段
        segments = 1
        current_sum = 0
        for x in nums:
            if current_sum + x > mid:
                segments += 1
                current_sum = x
                if segments > k:
                    return False
            else:
                current_sum += x
        return True

    while lo < hi:
        mid = (lo + hi) // 2
        if can_split(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo


